-- Arbeitsrecht Berufsbildung > Pflichten von Auszubildenden > Teilnahme an Berufsschule (§ 15 BBiG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss ein Fachinformatiker regelmäßig an der Berufsschule teilnehmen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 15 BBiG verpflichtet dazu"}, {"text": "Nein", "correct": false, "because": "Teilnahme ist gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Fachinformatiker die Berufsschule verweigern, wenn er im Betrieb gebraucht wird?', 2, '[{"text": "Nein", "correct": true, "because": "§ 15 BBiG hat Vorrang vor betrieblichen Anforderungen"}, {"text": "Ja", "correct": false, "because": "Berufsschule ist Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Fachinformatiker verpflichtet, sich auf Berufsschulprüfungen vorzubereiten?', 2, '[{"text": "Ja", "correct": true, "because": "§ 15 BBiG umfasst aktive Teilnahme"}, {"text": "Nein", "correct": false, "because": "Vorbereitung ist Teil der Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Fachinformatiker während der Berufsschulzeit im Betrieb arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "§ 15 BBiG fordert Freistellung für die Schule"}, {"text": "Ja", "correct": false, "because": "Berufsschule hat Vorrang"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Fachinformatiker den Betrieb über Berufsschultermine informieren?', 2, '[{"text": "Ja", "correct": true, "because": "Koordination ist Teil der Pflicht gemäß § 15 BBiG"}, {"text": "Nein", "correct": false, "because": "Information ist erforderlich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage verpflichtet einen Fachinformatiker zur Teilnahme an der Berufsschule?', 2, '[{"text": "§ 15 BBiG", "correct": true, "because": "Regelt die Berufsschulpflicht"}, {"text": "§ 13 BBiG", "correct": false, "because": "Bezieht sich auf allgemeine Pflichten"}, {"text": "§ 14 BBiG", "correct": false, "because": "Regelt Pflichten des Betriebs"}]'),
('00000000-0000-0000-0000-000000000000', 'Was sollte ein Fachinformatiker tun, wenn er die Berufsschule nicht besuchen kann?', 3, '[{"text": "Den Betrieb und die Schule informieren", "correct": true, "because": "§ 15 BBiG fordert verantwortliches Verhalten"}, {"text": "Ohne Meldung fernbleiben", "correct": false, "because": "Verstoß gegen die Pflicht"}, {"text": "Die IHK direkt kontaktieren", "correct": false, "because": "Nicht primäre Maßnahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist verpflichtet, einen Fachinformatiker für die Berufsschule freizustellen?', 2, '[{"text": "Der Ausbildungsbetrieb", "correct": true, "because": "§ 15 BBiG legt die Freistellungspflicht fest"}, {"text": "Die IHK", "correct": false, "because": "IHK organisiert nur"}, {"text": "Der Auszubildende selbst", "correct": false, "because": "Er hat keine Freistellungspflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Fachinformatiker die Berufsschule ohne Grund schwänzt?', 3, '[{"text": "Er kann verwarnt oder gekündigt werden", "correct": true, "because": "Verstoß gegen § 15 BBiG hat Konsequenzen"}, {"text": "Der Betrieb übernimmt die Schuld", "correct": false, "because": "Nicht vorgesehen"}, {"text": "Die Schule zahlt eine Strafe", "correct": false, "because": "Schule ist nicht verantwortlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tätigkeit gehört zur Berufsschulpflicht eines Fachinformatikers?', 3, '[{"text": "Teilnahme am Unterricht", "correct": true, "because": "Kern der Pflicht gemäß § 15 BBiG"}, {"text": "Arbeiten im Betrieb statt Schule", "correct": false, "because": "Widerspricht der Freistellung"}, {"text": "Private Projekte verfolgen", "correct": false, "because": "Nicht schulbezogen"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Pflicht eines Fachinformatikers bei der Berufsschule gemäß § 15 BBiG?', 4, '[{"text": "Regelmäßige Teilnahme", "correct": true, "because": "Kernpflicht der Berufsschule"}, {"text": "Vorbereitung auf Unterricht", "correct": true, "because": "Aktive Mitwirkung erforderlich"}, {"text": "Arbeiten im Betrieb statt Schule", "correct": false, "because": "Widerspricht der Pflicht"}, {"text": "Pünktliches Erscheinen", "correct": true, "because": "Teil der Zuverlässigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Gründe entschuldigen eine Nichtteilnahme an der Berufsschule für einen Fachinformatiker?', 3, '[{"text": "Krankheit", "correct": true, "because": "Entschuldigter Fehltritt"}, {"text": "Familiäre Notfälle", "correct": true, "because": "Gültiger Grund"}, {"text": "Persönliche Abneigung", "correct": false, "because": "Kein zulässiger Grund"}, {"text": "Betriebliche Projekte", "correct": false, "because": "Schule hat Vorrang"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unterstützung muss ein Betrieb einem Fachinformatiker für die Berufsschule bieten?', 4, '[{"text": "Freistellung während der Schulzeit", "correct": true, "because": "§ 15 BBiG schreibt es vor"}, {"text": "Bezahlte Arbeitszeit während der Schule", "correct": true, "because": "Vergütung bleibt erhalten"}, {"text": "Übernahme der Schulgebühren", "correct": false, "because": "Schule ist kostenfrei"}, {"text": "Transport zur Schule", "correct": false, "because": "Nicht vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen drohen einem Fachinformatiker bei Verstoß gegen die Berufsschulpflicht?', 3, '[{"text": "Verwarnung durch den Betrieb", "correct": true, "because": "Reaktion auf Pflichtverletzung"}, {"text": "Kündigung bei Wiederholung", "correct": true, "because": "§ 22 BBiG erlaubt dies"}, {"text": "Automatische Prüfungsanmeldung", "correct": false, "because": "Nicht logisch"}, {"text": "Meldung an die Schule", "correct": true, "because": "Schule kann informiert werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Was darf ein Fachinformatiker während der Berufsschulzeit nicht tun?', 3, '[{"text": "Im Betrieb arbeiten", "correct": true, "because": "§ 15 BBiG fordert Freistellung"}, {"text": "Private Projekte bearbeiten", "correct": true, "because": "Nicht schulbezogen"}, {"text": "Am Unterricht teilnehmen", "correct": false, "because": "Das ist seine Pflicht"}, {"text": "Hausaufgaben machen", "correct": false, "because": "Teil der Pflicht"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Fachinformatiker muss die Berufsschule besuchen. b) Der Betrieb kann die Teilnahme verbieten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Besuch ist Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) widerspricht § 15 BBiG"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Berufsschulpflicht gilt auch in der Probezeit. b) Ein Fachinformatiker muss sich auf den Unterricht vorbereiten.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "§ 15 BBiG gilt immer, Vorbereitung erforderlich"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Fachinformatiker darf die Berufsschule schwänzen, wenn er krank ist. b) Der Betrieb muss ihn für die Schule freistellen.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Krankheit entschuldigt, Freistellung ist Pflicht"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Berufsschulpflicht endet mit der IHK-Prüfung. b) Ein Fachinformatiker muss den Betrieb über Schulzeiten informieren.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": true, "because": "Pflicht gilt bis Ausbildungsende, b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Fachinformatiker kann die Berufsschule ignorieren, wenn er alles weiß. b) Verstöße gegen die Schulpflicht können zur Kündigung führen.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": true, "because": "Kündigung möglich, a) ist falsch"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

